import os

def solve(path):
    name = os.path.basename(os.fspath(path)).casefold()
    parts = name.split('.')
    if len(parts) >= 3 and parts[-2] == 'tar' and parts[-1] in ('gz', 'bz2', 'xz'):
        return 'archive'
    if name.endswith('.gz'):
        return 'compressed'
    return 'other'
